import React from 'react';
import { 
  Box, Grid, Paper, Typography, 
  Card, CardContent, Divider
} from '@mui/material';
import WarningIcon from '@mui/icons-material/Warning';
import ChatIcon from '@mui/icons-material/Chat';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import AssessmentIcon from '@mui/icons-material/Assessment';

// Cyberpunk color theme matching the ComplaintTrackingChart
const cyberpunkColors = {
  neon: {
    green: '#00ff41',
    brightGreen: '#39ff14',
    darkGreen: '#008f11',
    accent: '#0abdc6',
    yellow: '#caff70'
  },
  dark: {
    base: '#0d0208',
    secondary: '#0f100f',
    accent: '#121212'
  },
  text: {
    primary: '#00ff41',
    secondary: '#465b49'
  }
};

const SummaryStats = ({ analyzedData }) => {
  if (!analyzedData) return null;
  
  const { complaintPercentage = 0, chunks = [], utterances = [] } = analyzedData;
  
  // Calculate stats
  const complaintChunks = chunks.filter(chunk => chunk.isComplaint).length;
  const totalChunks = chunks.length;
  const complaintRatio = totalChunks ? `${complaintChunks}/${totalChunks}` : '0/0';
  const complaintPercentageText = `${Math.round(complaintPercentage)}%`;
  
  // Count speaker types
  const speakerCount = {};
  if (utterances && utterances.length) {
    utterances.forEach(utterance => {
      if (utterance.speaker) {
        speakerCount[utterance.speaker] = (speakerCount[utterance.speaker] || 0) + 1;
      }
    });
  }
  
  // Determine severity level based on percentage
  let severityLevel = 'Low';
  let severityColor = cyberpunkColors.neon.green;
  let severityShadow = '0 0 10px #008f11';
  
  if (complaintPercentage >= 70) {
    severityLevel = 'High';
    severityColor = '#ff3e3e';
    severityShadow = '0 0 10px #ff0000';
  } else if (complaintPercentage >= 40) {
    severityLevel = 'Medium';
    severityColor = '#ffdc3e';
    severityShadow = '0 0 10px #ffa500';
  }
  
  // Check if we have any caller utterances
  const callerUtterances = Object.entries(speakerCount)
    .filter(([speaker]) => speaker.toLowerCase().includes('caller') || speaker.toLowerCase().includes('customer'))
    .reduce((total, [_, count]) => total + count, 0);
  
  const agentUtterances = Object.entries(speakerCount)
    .filter(([speaker]) => speaker.toLowerCase().includes('agent') || speaker.toLowerCase().includes('rep'))
    .reduce((total, [_, count]) => total + count, 0);
  
  // Calculate estimated caller complaints
  const callerComplaints = Math.round(complaintPercentage * callerUtterances / 100);
  const callerComplaintRatio = `~${callerComplaints}/${callerUtterances}`;
  
  // Format analysis period
  let analysisPeriod = 'N/A';
  if (chunks.length > 0 && chunks[0].timestamp) {
    const firstTime = new Date(chunks[0].timestamp);
    const lastTime = new Date(chunks[chunks.length - 1].timestamp);
    const diffMs = lastTime - firstTime;
    analysisPeriod = `${firstTime.toLocaleTimeString()} - ${lastTime.toLocaleTimeString()}(${(diffMs / 1000).toFixed(1)} seconds)`;
  }
  
  // Common cyberpunk styles
  const cyberpunkCardStyle = {
    background: `linear-gradient(135deg, ${cyberpunkColors.dark.base} 0%, ${cyberpunkColors.dark.secondary} 100%)`,
    border: `1px solid ${cyberpunkColors.neon.green}`,
    boxShadow: `0 0 15px ${cyberpunkColors.neon.darkGreen}`,
    borderRadius: '0.5rem',
    height: '100%'
  };
  
  const cardHeaderStyle = {
    color: '#465b49',
    textTransform: 'uppercase',
    fontFamily: 'monospace',
    fontSize: '0.75rem',
    letterSpacing: '0.1em',
    fontWeight: 'bold',
    display: 'flex',
    alignItems: 'center',
    mb: 1
  };
  
  const cardValueStyle = {
    color: cyberpunkColors.neon.green,
    fontFamily: 'monospace',
    fontWeight: 'bold',
    textShadow: '0 0 5px rgba(0, 255, 65, 0.5)'
  };
  
  const cardFooterStyle = {
    color: '#465b49',
    fontSize: '0.7rem',
    fontFamily: 'monospace',
    mt: 1
  };
  
  return (
    <Box sx={{ mb: 3 }}>
      <Typography variant="h6" fontFamily="monospace" color={cyberpunkColors.neon.green} 
        sx={{ 
          mb: 2, 
          textTransform: 'uppercase', 
          letterSpacing: '0.1em',
          textShadow: '0 0 5px rgba(0, 255, 65, 0.5)',
          fontWeight: 'bold'
        }}>
        // SYSTEM DATA ANALYSIS //
      </Typography>
      
      <Grid container spacing={2} sx={{ mb: 2 }}>
        <Grid item xs={12} sm={6} md={3}>
          <Box sx={cyberpunkCardStyle}>
            <Box sx={{ p: 2 }}>
              <Typography sx={cardHeaderStyle}>
                <WarningIcon sx={{ mr: 1, fontSize: '1rem', color: severityColor }} /> 
                Complaint Severity
              </Typography>
              <Typography variant="h5" sx={{
                ...cardValueStyle,
                color: severityColor,
                textShadow: severityShadow
              }}>
                {severityLevel}
              </Typography>
              <Typography sx={cardFooterStyle}>
                Based on percentage
              </Typography>
            </Box>
          </Box>
        </Grid>
        
        <Grid item xs={12} sm={6} md={3}>
          <Box sx={cyberpunkCardStyle}>
            <Box sx={{ p: 2 }}>
              <Typography sx={cardHeaderStyle}>
                <AssessmentIcon sx={{ mr: 1, fontSize: '1rem', color: cyberpunkColors.neon.green }} /> 
                Complaint Chunks
              </Typography>
              <Typography variant="h5" sx={cardValueStyle}>
                {complaintRatio}
              </Typography>
              <Typography sx={cardFooterStyle}>
                {complaintPercentageText} of chunks
              </Typography>
            </Box>
          </Box>
        </Grid>
        
        <Grid item xs={12} sm={6} md={3}>
          <Box sx={cyberpunkCardStyle}>
            <Box sx={{ p: 2 }}>
              <Typography sx={cardHeaderStyle}>
                <ChatIcon sx={{ mr: 1, fontSize: '1rem', color: cyberpunkColors.neon.accent }} /> 
                Total Utterances
              </Typography>
              <Typography variant="h5" sx={cardValueStyle}>
                {utterances.length}
              </Typography>
              <Typography sx={cardFooterStyle}>
                {callerUtterances} caller, {agentUtterances} agent
              </Typography>
            </Box>
          </Box>
        </Grid>
        
        <Grid item xs={12} sm={6} md={3}>
          <Box sx={cyberpunkCardStyle}>
            <Box sx={{ p: 2 }}>
              <Typography sx={cardHeaderStyle}>
                <WarningIcon sx={{ mr: 1, fontSize: '1rem', color: '#ff9800' }} /> 
                Caller Complaints
              </Typography>
              <Typography variant="h5" sx={cardValueStyle}>
                {callerComplaintRatio}
              </Typography>
              <Typography sx={cardFooterStyle}>
                Estimated from chunks
              </Typography>
            </Box>
          </Box>
        </Grid>
      </Grid>
      
      <Box sx={{
        display: 'flex',
        alignItems: 'center',
        p: 1,
        borderRadius: '0.25rem',
        background: 'rgba(0, 20, 0, 0.7)',
        border: `1px solid ${cyberpunkColors.neon.darkGreen}`,
        boxShadow: `0 0 10px ${cyberpunkColors.neon.darkGreen}`,
        mb: 4,
        fontFamily: 'monospace'
      }}>
        <AccessTimeIcon sx={{ color: cyberpunkColors.neon.green, mr: 1, fontSize: '1rem' }} />
        <Typography variant="caption" sx={{ color: cyberpunkColors.neon.darkGreen, fontFamily: 'monospace' }}>
          Analysis period: {analysisPeriod}
        </Typography>
      </Box>
    </Box>
  );
};

export default SummaryStats;
